-- ПОСЛЕ применения 0229 (сначала db/ops/preflight.sql: 0229 APPLIED). Для Павла, SQL Editor, по блокам. Продолжение скриптов 2026-11-27 (/mnt/project-files/pay-mode-return/).
-- Что делает: Fedorov Lev и Matvey получают период «за визит» 01.11 — 01.12 (pay_mode_from = 2026-11-01, pay_mode_until = 2026-12-01), после чего ноябрь для них «за визит» по правилу базы,
-- и временные ноябрьские строки со списанием («ноябрь: оплата за визит, абонемент не нужен») можно снять. Строки остаются (пустые, сумма 0), платежи, декабрь и визиты не меняются.
-- Блоки выполнять целиком; внутри do-блока нет пустых строк и комментариев.

-- БЛОК 0. Предпросмотр: ожидается Lev subscription без дат, Matvey subscription без дат (после скриптов 27.11), ноябрьские строки written_off = true.
select p.full_name, p.pay_mode, p.pay_mode_from, p.pay_mode_until, s.month, s.amount_due, s.written_off, s.closed_reason from players p left join subscriptions s on s.player_id = p.id and s.month = '2026-11-01' where p.id in ('f0265223-6ddf-4d3c-8e46-eabc28ab8064', '149de297-a8d9-4948-b540-8d438082fafd') order by p.full_name;

-- БЛОК 1. Применение.
do $$ declare r record; begin for r in select id from players where id in ('f0265223-6ddf-4d3c-8e46-eabc28ab8064', '149de297-a8d9-4948-b540-8d438082fafd') loop if not exists (select 1 from players where id = r.id and pay_mode = 'subscription' and pay_mode_from is null and pay_mode_until is null) then raise exception 'игрок % не в ожидаемом состоянии', r.id; end if; update players set pay_mode_from = date '2026-11-01', pay_mode_until = date '2026-12-01' where id = r.id; update subscriptions set written_off = false, closed_kind = null, closed_reason = null, closed_at = null, closed_by = null where player_id = r.id and month = date '2026-11-01' and written_off and closed_reason = 'ноябрь: оплата за визит, абонемент не нужен' and amount_due = 0; insert into audit_log (actor_id, action, entity, entity_id, before, after) values (null, 'player_pay_mode', 'players', r.id, jsonb_build_object('pay_mode', 'subscription', 'pay_mode_from', null, 'pay_mode_until', null), jsonb_build_object('pay_mode', 'subscription', 'pay_mode_from', date '2026-11-01', 'pay_mode_until', date '2026-12-01')); end loop; end $$;

-- БЛОК 2. Проверка: период записан, ноябрьские строки не списаны; «Должники» и карточка не показывают ноябрь как абонемент.
select p.full_name, p.pay_mode, p.pay_mode_from, p.pay_mode_until, s.month, s.amount_due, s.written_off from players p left join subscriptions s on s.player_id = p.id and s.month >= '2026-11-01' where p.id in ('f0265223-6ddf-4d3c-8e46-eabc28ab8064', '149de297-a8d9-4948-b540-8d438082fafd') order by p.full_name, s.month;

-- ОТКАТ (если нужно вернуть как было после скриптов 27.11): период снимается, ноябрь снова списан.
-- do $$ declare r record; begin for r in select id from players where id in ('f0265223-6ddf-4d3c-8e46-eabc28ab8064', '149de297-a8d9-4948-b540-8d438082fafd') loop update players set pay_mode_from = null, pay_mode_until = null where id = r.id and pay_mode = 'subscription' and pay_mode_from = date '2026-11-01' and pay_mode_until = date '2026-12-01'; update subscriptions set written_off = true, closed_kind = 'forgiven', closed_reason = 'ноябрь: оплата за визит, абонемент не нужен' where player_id = r.id and month = date '2026-11-01' and amount_due = 0 and not written_off; end loop; end $$;
